mapper.update:
UPDATE person_profile SET
real_name=#{realName},status=#{status},revision=#{revision},updated_at=#{updatedAt},last_change_id=#{lastChangeId}
WHERE id=#{id} AND revision=#{revision}-1

UPDATE person_identifier SET
value_masked=#{valueMasked},private_value=#{privateValue},verification=#{verification},status=#{status},revision=#{revision},source_reference=#{sourceReference}
WHERE id=#{id} AND person_id=#{personId} AND revision=#{revision}-1

UPDATE person_account_binding SET
status='ENDED',revision=#{revision},ended_at=#{endedAt},ended_by=#{endedBy},end_reason=#{endReason}
WHERE id=#{id} AND status='ACTIVE' AND revision=#{revision}-1
